    }

}

int RENAME(swri_resample)(ResampleContext *c, DELEM *dst, const DELEM *src, int *consumed, int src_size, int dst_size, int update_ctx){

    int dst_index, i;

    int index= c->index;

    int frac= c->frac;

    int dst_incr_frac= c->dst_incr % c->src_incr;

    int dst_incr=      c->dst_incr / c->src_incr;

    int compensation_distance= c->compensation_distance;



    av_assert1(c->filter_shift == FILTER_SHIFT);

    av_assert1(c->felem_size == sizeof(FELEM));



    if(compensation_distance == 0 && c->filter_length == 1 && c->phase_shift==0){

        int64_t index2= (1LL<<32)*c->frac/c->src_incr + (1LL<<32)*index;

        int64_t incr= (1LL<<32) * c->dst_incr / c->src_incr;

        int new_size = (src_size * (int64_t)c->src_incr - frac + c->dst_incr - 1) / c->dst_incr;



        dst_size= FFMIN(dst_size, new_size);



        for(dst_index=0; dst_index < dst_size; dst_index++){

            dst[dst_index] = src[index2>>32];

            index2 += incr;

        }

        index += dst_index * dst_incr;

        index += (frac + dst_index * (int64_t)dst_incr_frac) / c->src_incr;

        frac   = (frac + dst_index * (int64_t)dst_incr_frac) % c->src_incr;

        av_assert2(index >= 0);

        *consumed= index;

        index = 0;

    } else if (compensation_distance == 0 && index >= 0) {

        int64_t end_index = (1 + src_size - c->filter_length) << c->phase_shift;

        int64_t delta_frac = (end_index - index) * c->src_incr - c->frac;

        int delta_n = (delta_frac + c->dst_incr - 1) / c->dst_incr;

        int n = FFMIN(dst_size, delta_n);

        int sample_index;



        if (!c->linear) {

            sample_index = index >> c->phase_shift;

            index &= c->phase_mask;

            for (dst_index = 0; dst_index < n; dst_index++) {

                FELEM *filter = ((FELEM *) c->filter_bank) + c->filter_alloc * index;



#ifdef COMMON_CORE

                COMMON_CORE

#else

                FELEM2 val=0;

                for (i = 0; i < c->filter_length; i++) {

                    val += src[sample_index + i] * (FELEM2)filter[i];

                }

                OUT(dst[dst_index], val);

#endif



                frac += dst_incr_frac;

                index += dst_incr;

                if (frac >= c->src_incr) {

                    frac -= c->src_incr;

                    index++;

                }

                sample_index += index >> c->phase_shift;

                index &= c->phase_mask;

            }

        } else {

            sample_index = index >> c->phase_shift;

            index &= c->phase_mask;

            for (dst_index = 0; dst_index < n; dst_index++) {

                FELEM *filter = ((FELEM *) c->filter_bank) + c->filter_alloc * index;

                FELEM2 val=0, v2 = 0;



#ifdef LINEAR_CORE

                LINEAR_CORE

#else

                for (i = 0; i < c->filter_length; i++) {

                    val += src[sample_index + i] * (FELEM2)filter[i];

                    v2  += src[sample_index + i] * (FELEM2)filter[i + c->filter_alloc];

                }

#endif

                val += (v2 - val) * (FELEML) frac / c->src_incr;

                OUT(dst[dst_index], val);



                frac += dst_incr_frac;

                index += dst_incr;

                if (frac >= c->src_incr) {

                    frac -= c->src_incr;

                    index++;

                }

                sample_index += index >> c->phase_shift;

                index &= c->phase_mask;

            }

        }



        *consumed = sample_index;

    } else {

        int sample_index = 0;

        for(dst_index=0; dst_index < dst_size; dst_index++){

            FELEM *filter;

            FELEM2 val=0;



            sample_index += index >> c->phase_shift;

            index &= c->phase_mask;

            filter = ((FELEM*)c->filter_bank) + c->filter_alloc*index;



            if(sample_index + c->filter_length > src_size || -sample_index >= src_size){

                break;

            }else if(sample_index < 0){

                for(i=0; i<c->filter_length; i++)

                    val += src[FFABS(sample_index + i)] * (FELEM2)filter[i];

                OUT(dst[dst_index], val);

            }else if(c->linear){

                FELEM2 v2=0;

#ifdef LINEAR_CORE

                LINEAR_CORE

#else

                for(i=0; i<c->filter_length; i++){

                    val += src[sample_index + i] * (FELEM2)filter[i];

                    v2  += src[sample_index + i] * (FELEM2)filter[i + c->filter_alloc];

                }

#endif

                val+=(v2-val)*(FELEML)frac / c->src_incr;

                OUT(dst[dst_index], val);

            }else{

#ifdef COMMON_CORE

                COMMON_CORE

#else

                for(i=0; i<c->filter_length; i++){

                    val += src[sample_index + i] * (FELEM2)filter[i];

                }

                OUT(dst[dst_index], val);

#endif

            }



            frac += dst_incr_frac;

            index += dst_incr;

            if(frac >= c->src_incr){

                frac -= c->src_incr;

                index++;

            }



            if(dst_index + 1 == compensation_distance){

                compensation_distance= 0;

                dst_incr_frac= c->ideal_dst_incr % c->src_incr;

                dst_incr=      c->ideal_dst_incr / c->src_incr;

            }

        }

        *consumed= FFMAX(sample_index, 0);

        index += FFMIN(sample_index, 0) << c->phase_shift;



        if(compensation_distance){

            compensation_distance -= dst_index;

            av_assert1(compensation_distance > 0);

        }

    }



    if(update_ctx){

        c->frac= frac;

        c->index= index;

        c->dst_incr= dst_incr_frac + c->src_incr*dst_incr;

        c->compensation_distance= compensation_distance;

    }



    return dst_index;

}

static inline void RENAME(rgb32tobgr15)(const uint8_t *src, uint8_t *dst, int src_size)

{

    const uint8_t *s = src;

    const uint8_t *end;

    const uint8_t *mm_end;

    uint16_t *d = (uint16_t *)dst;

    end = s + src_size;

    __asm__ volatile(PREFETCH"    %0"::"m"(*src):"memory");

    __asm__ volatile(

        "movq          %0, %%mm7    \n\t"

        "movq          %1, %%mm6    \n\t"

        ::"m"(red_15mask),"m"(green_15mask));

    mm_end = end - 15;

    while (s < mm_end) {

        __asm__ volatile(

            PREFETCH"    32%1           \n\t"

            "movd          %1, %%mm0    \n\t"

            "movd         4%1, %%mm3    \n\t"

            "punpckldq    8%1, %%mm0    \n\t"

            "punpckldq   12%1, %%mm3    \n\t"

            "movq       %%mm0, %%mm1    \n\t"

            "movq       %%mm0, %%mm2    \n\t"

            "movq       %%mm3, %%mm4    \n\t"

            "movq       %%mm3, %%mm5    \n\t"

            "psllq         $7, %%mm0    \n\t"

            "psllq         $7, %%mm3    \n\t"

            "pand       %%mm7, %%mm0    \n\t"

            "pand       %%mm7, %%mm3    \n\t"

            "psrlq         $6, %%mm1    \n\t"

            "psrlq         $6, %%mm4    \n\t"

            "pand       %%mm6, %%mm1    \n\t"

            "pand       %%mm6, %%mm4    \n\t"

            "psrlq        $19, %%mm2    \n\t"

            "psrlq        $19, %%mm5    \n\t"

            "pand          %2, %%mm2    \n\t"

            "pand          %2, %%mm5    \n\t"

            "por        %%mm1, %%mm0    \n\t"

            "por        %%mm4, %%mm3    \n\t"

            "por        %%mm2, %%mm0    \n\t"

            "por        %%mm5, %%mm3    \n\t"

            "psllq        $16, %%mm3    \n\t"

            "por        %%mm3, %%mm0    \n\t"

            MOVNTQ"     %%mm0, %0       \n\t"

            :"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

        d += 4;

        s += 16;

    }

    __asm__ volatile(SFENCE:::"memory");

    __asm__ volatile(EMMS:::"memory");

    while (s < end) {

        register int rgb = *(const uint32_t*)s; s += 4;

        *d++ = ((rgb&0xF8)<<7) + ((rgb&0xF800)>>6) + ((rgb&0xF80000)>>19);

    }

}

static inline void RENAME(rgb24tobgr16)(const uint8_t *src, uint8_t *dst, long src_size)

{

	const uint8_t *s = src;

	const uint8_t *end;

#ifdef HAVE_MMX

	const uint8_t *mm_end;

#endif

	uint16_t *d = (uint16_t *)dst;

	end = s + src_size;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*src):"memory");

	__asm __volatile(

	    "movq	%0, %%mm7\n\t"

	    "movq	%1, %%mm6\n\t"

	    ::"m"(red_16mask),"m"(green_16mask));

	mm_end = end - 15;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movd	%1, %%mm0\n\t"

		"movd	3%1, %%mm3\n\t"

		"punpckldq 6%1, %%mm0\n\t"

		"punpckldq 9%1, %%mm3\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm0, %%mm2\n\t"

		"movq	%%mm3, %%mm4\n\t"

		"movq	%%mm3, %%mm5\n\t"

		"psllq	$8, %%mm0\n\t"

		"psllq	$8, %%mm3\n\t"

		"pand	%%mm7, %%mm0\n\t"

		"pand	%%mm7, %%mm3\n\t"

		"psrlq	$5, %%mm1\n\t"

		"psrlq	$5, %%mm4\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm4\n\t"

		"psrlq	$19, %%mm2\n\t"

		"psrlq	$19, %%mm5\n\t"

		"pand	%2, %%mm2\n\t"

		"pand	%2, %%mm5\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm2, %%mm0\n\t"

		"por	%%mm5, %%mm3\n\t"

		"psllq	$16, %%mm3\n\t"

		"por	%%mm3, %%mm0\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		:"=m"(*d):"m"(*s),"m"(blue_16mask):"memory");

		d += 4;

		s += 12;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		const int r= *s++;

		const int g= *s++;

		const int b= *s++;

		*d++ = (b>>3) | ((g&0xFC)<<3) | ((r&0xF8)<<8);

	}

}

static inline void RENAME(rgb24ToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, int width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    assert(src1==src2);

    RENAME(bgr24ToUV_mmx)(dstU, dstV, src1, width, PIX_FMT_RGB24);

#else

    int i;

    assert(src1==src2);

    for (i=0; i<width; i++) {

        int r= src1[3*i + 0];

        int g= src1[3*i + 1];

        int b= src1[3*i + 2];



        dstU[i]= (RU*r + GU*g + BU*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

        dstV[i]= (RV*r + GV*g + BV*b + (257<<(RGB2YUV_SHIFT-1)))>>RGB2YUV_SHIFT;

    }

#endif

}

static av_always_inline void RENAME(decode_line)(FFV1Context *s, int w,

                                                 TYPE *sample[2],

                                                 int plane_index, int bits)

{

    PlaneContext *const p = &s->plane[plane_index];

    RangeCoder *const c   = &s->c;

    int x;

    int run_count = 0;

    int run_mode  = 0;

    int run_index = s->run_index;



    if (s->slice_coding_mode == 1) {

        int i;

        for (x = 0; x < w; x++) {

            int v = 0;

            for (i=0; i<bits; i++) {

                uint8_t state = 128;

                v += v + get_rac(c, &state);

            }

            sample[1][x] = v;

        }

        return;

    }



    for (x = 0; x < w; x++) {

        int diff, context, sign;



        context = RENAME(get_context)(p, sample[1] + x, sample[0] + x, sample[1] + x);

        if (context < 0) {

            context = -context;

            sign    = 1;

        } else

            sign = 0;



        av_assert2(context < p->context_count);



        if (s->ac != AC_GOLOMB_RICE) {

            diff = get_symbol_inline(c, p->state[context], 1);

        } else {

            if (context == 0 && run_mode == 0)

                run_mode = 1;



            if (run_mode) {

                if (run_count == 0 && run_mode == 1) {

                    if (get_bits1(&s->gb)) {

                        run_count = 1 << ff_log2_run[run_index];

                        if (x + run_count <= w)

                            run_index++;

                    } else {

                        if (ff_log2_run[run_index])

                            run_count = get_bits(&s->gb, ff_log2_run[run_index]);

                        else

                            run_count = 0;

                        if (run_index)

                            run_index--;

                        run_mode = 2;

                    }

                }

                run_count--;

                if (run_count < 0) {

                    run_mode  = 0;

                    run_count = 0;

                    diff      = get_vlc_symbol(&s->gb, &p->vlc_state[context],

                                               bits);

                    if (diff >= 0)

                        diff++;

                } else

                    diff = 0;

            } else

                diff = get_vlc_symbol(&s->gb, &p->vlc_state[context], bits);



            ff_dlog(s->avctx, "count:%d index:%d, mode:%d, x:%d pos:%d\n",

                    run_count, run_index, run_mode, x, get_bits_count(&s->gb));

        }



        if (sign)

            diff = -diff;



        sample[1][x] = av_mod_uintp2(RENAME(predict)(sample[1] + x, sample[0] + x) + (SUINT)diff, bits);

    }

    s->run_index = run_index;

}

static void RENAME(mix8to2)(SAMPLE **out, const SAMPLE **in, COEFF *coeffp, integer len){

    int i;



    for(i=0; i<len; i++) {

        INTER t = in[2][i]*coeffp[0*8+2] + in[3][i]*coeffp[0*8+3];

        out[0][i] = R(t + in[0][i]*(INTER)coeffp[0*8+0] + in[4][i]*(INTER)coeffp[0*8+4] + in[6][i]*(INTER)coeffp[0*8+6]);

        out[1][i] = R(t + in[1][i]*(INTER)coeffp[1*8+1] + in[5][i]*(INTER)coeffp[1*8+5] + in[7][i]*(INTER)coeffp[1*8+7]);

    }

}

static int RENAME(dct_quantize)(MpegEncContext *s,

                            DCTELEM *block, int n,

                            int qscale, int *overflow)

{

    int level=0, last_non_zero_p1, q; //=0 is cuz gcc says uninitalized ...

    const uint16_t *qmat, *bias;

    static __align8 int16_t temp_block[64];



    //s->fdct (block);

    ff_fdct_mmx (block); //cant be anything else ...



    if (s->mb_intra) {

        int dummy;

        if (n < 4)

            q = s->y_dc_scale;

        else

            q = s->c_dc_scale;

        /* note: block[0] is assumed to be positive */

        if (!s->h263_aic) {

#if 1

        asm volatile (

        	"imul %%ecx		\n\t"

        	: "=d" (level), "=a"(dummy)

        	: "a" ((block[0]>>2) + q), "c" (inverse[q<<1])

        );

#else

        asm volatile (

        	"xorl %%edx, %%edx	\n\t"

        	"divw %%cx		\n\t"

        	"movzwl %%ax, %%eax	\n\t"

        	: "=a" (level)

        	: "a" ((block[0]>>2) + q), "c" (q<<1)

        	: "%edx"

        );

#endif

        } else

            /* For AIC we skip quant/dequant of INTRADC */

            level = (block[0] + 4)>>3;



        block[0]=0; //avoid fake overflow

//        temp_block[0] = (block[0] + (q >> 1)) / q;

        last_non_zero_p1 = 1;

        bias = s->q_intra_matrix16_bias[qscale];

        qmat = s->q_intra_matrix16[qscale];

    } else {

        last_non_zero_p1 = 0;

        bias = s->q_inter_matrix16_bias[qscale];

        qmat = s->q_inter_matrix16[qscale];

    }



    if(s->out_format == FMT_H263 && s->mpeg_quant==0){

	  /* PROLOGUE */

        asm volatile(

            "movd %%eax, %%mm3			\n\t" // last_non_zero_p1

            SPREADW(%%mm3)

            "pxor %%mm7, %%mm7			\n\t" // 0

            "pxor %%mm4, %%mm4			\n\t" // 0

            "movq (%1), %%mm5			\n\t" // qmat[0]

            "pxor %%mm6, %%mm6			\n\t"

            "psubw (%2), %%mm6			\n\t" // -bias[0]

            "movl $-128, %%eax			\n\t"

            : "+a" (last_non_zero_p1)

            : "r" (qmat), "r" (bias)

            );

	  /* CORE */

	  asm volatile(

            ".balign 16				\n\t"

            "1:					\n\t"

            "pxor %%mm1, %%mm1			\n\t" // 0

            "movq (%1, %%eax), %%mm0		\n\t" // block[i]

            "pcmpgtw %%mm0, %%mm1		\n\t" // block[i] <= 0 ? 0xFF : 0x00

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // ABS(block[i])

            "psubusw %%mm6, %%mm0		\n\t" // ABS(block[i]) + bias[0]

            "pmulhw %%mm5, %%mm0		\n\t" // (ABS(block[i])*qmat[0] - bias[0]*qmat[0])>>16

            "por %%mm0, %%mm4			\n\t" 

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // out=((ABS(block[i])*qmat[0] - bias[0]*qmat[0])>>16)*sign(block[i])

            "movq %%mm0, (%3, %%eax)		\n\t"

            "pcmpeqw %%mm7, %%mm0		\n\t" // out==0 ? 0xFF : 0x00

            "movq (%2, %%eax), %%mm1		\n\t" 

            "movq %%mm7, (%1, %%eax)		\n\t" // 0

            "pandn %%mm1, %%mm0			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "addl $8, %%eax			\n\t"

            " js 1b				\n\t"

            : "+a" (last_non_zero_p1)

            : "r" (block+64), "r" (inv_zigzag_direct16+64), "r" (temp_block+64)

            );

	  /* EPILOGUE */

	  asm volatile(

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $32, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $16, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movd %%mm3, %%eax			\n\t"

            "movzbl %%al, %%eax			\n\t" // last_non_zero_p1

            "movd %2, %%mm1			\n\t" // max_qcoeff

	    SPREADW(%%mm1)

            "psubusw %%mm1, %%mm4		\n\t" 

            "packuswb %%mm4, %%mm4		\n\t"

            "movd %%mm4, %1			\n\t" // *overflow

            : "+a" (last_non_zero_p1), "=r" (*overflow)

            : "r" (s->max_qcoeff)

            );

    }else{ // FMT_H263

        asm volatile(

            "pushl %%ebp				\n\t"

            "pushl %%ebx				\n\t"

            "movl %0, %%ebp				\n\t"

            "movl (%%ebp), %%ebx		\n\t"

            "movd %%ebx, %%mm3			\n\t" // last_non_zero_p1

            SPREADW(%%mm3)

            "pxor %%mm7, %%mm7			\n\t" // 0

            "pxor %%mm4, %%mm4			\n\t" // 0

            "movl $-128, %%ebx			\n\t"

            ".balign 16				\n\t"

            "1:					\n\t"

            "pxor %%mm1, %%mm1			\n\t" // 0

            "movq (%1, %%ebx), %%mm0		\n\t" // block[i]

            "pcmpgtw %%mm0, %%mm1		\n\t" // block[i] <= 0 ? 0xFF : 0x00

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // ABS(block[i])

            "movq (%3, %%ebx), %%mm6		\n\t" // bias[0]

            "paddusw %%mm6, %%mm0		\n\t" // ABS(block[i]) + bias[0]

            "movq (%2, %%ebx), %%mm5		\n\t" // qmat[i]

            "pmulhw %%mm5, %%mm0		\n\t" // (ABS(block[i])*qmat[0] + bias[0]*qmat[0])>>16

            "por %%mm0, %%mm4			\n\t" 

            "pxor %%mm1, %%mm0			\n\t" 

            "psubw %%mm1, %%mm0			\n\t" // out=((ABS(block[i])*qmat[0] - bias[0]*qmat[0])>>16)*sign(block[i])

            "movq %%mm0, (%5, %%ebx)		\n\t"

            "pcmpeqw %%mm7, %%mm0		\n\t" // out==0 ? 0xFF : 0x00

            "movq (%4, %%ebx), %%mm1		\n\t" 

            "movq %%mm7, (%1, %%ebx)		\n\t" // 0

            "pandn %%mm1, %%mm0			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "addl $8, %%ebx			\n\t"

            " js 1b				\n\t"

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $32, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movq %%mm3, %%mm0			\n\t"

            "psrlq $16, %%mm3			\n\t"

	    PMAXW(%%mm0, %%mm3)

            "movd %%mm3, %%ebx			\n\t"

            "movzbl %%bl, %%ebx			\n\t" // last_non_zero_p1

            "movl %%ebx, (%%ebp)		\n\t"

            "popl %%ebx					\n\t"

            "popl %%ebp					\n\t"

            :

			: "m" (last_non_zero_p1),

              "r" (block+64), "r" (qmat+64), "r" (bias+64),

              "r" (inv_zigzag_direct16+64), "r" (temp_block+64)

        );

        // note the asm is split cuz gcc doesnt like that many operands ...

        asm volatile(

            "movd %1, %%mm1			\n\t" // max_qcoeff

	    SPREADW(%%mm1)

            "psubusw %%mm1, %%mm4		\n\t" 

            "packuswb %%mm4, %%mm4		\n\t"

            "movd %%mm4, %0			\n\t" // *overflow

        : "=r" (*overflow)

        : "r" (s->max_qcoeff)

        );

    }



    if(s->mb_intra) block[0]= level;

    else            block[0]= temp_block[0];



    if(s->dsp.idct_permutation_type == FF_SIMPLE_IDCT_PERM){

        if(last_non_zero_p1 <= 1) goto end;

        block[0x08] = temp_block[0x01]; block[0x10] = temp_block[0x08]; 

        block[0x20] = temp_block[0x10]; 

        if(last_non_zero_p1 <= 4) goto end;

        block[0x18] = temp_block[0x09]; block[0x04] = temp_block[0x02]; 

        block[0x09] = temp_block[0x03]; 

        if(last_non_zero_p1 <= 7) goto end;

        block[0x14] = temp_block[0x0A]; block[0x28] = temp_block[0x11]; 

        block[0x12] = temp_block[0x18]; block[0x02] = temp_block[0x20]; 

        if(last_non_zero_p1 <= 11) goto end;

        block[0x1A] = temp_block[0x19]; block[0x24] = temp_block[0x12]; 

        block[0x19] = temp_block[0x0B]; block[0x01] = temp_block[0x04]; 

        block[0x0C] = temp_block[0x05]; 

        if(last_non_zero_p1 <= 16) goto end;

        block[0x11] = temp_block[0x0C]; block[0x29] = temp_block[0x13]; 

        block[0x16] = temp_block[0x1A]; block[0x0A] = temp_block[0x21]; 

        block[0x30] = temp_block[0x28]; block[0x22] = temp_block[0x30]; 

        block[0x38] = temp_block[0x29]; block[0x06] = temp_block[0x22]; 

        if(last_non_zero_p1 <= 24) goto end;

        block[0x1B] = temp_block[0x1B]; block[0x21] = temp_block[0x14]; 

        block[0x1C] = temp_block[0x0D]; block[0x05] = temp_block[0x06]; 

