// 0, 2, 3, 1

#define REAL_DERING_CORE(dst,src,ppsx,psx,sx,pplx,plx,lx,t0,t1) \

        "movq " #src ", " #sx "                 \n\t" /* src[0] */\

        "movq " #sx ", " #lx "                  \n\t" /* src[0] */\

        "movq " #sx ", " #t0 "                  \n\t" /* src[0] */\

        "psllq $8, " #lx "                      \n\t"\

        "psrlq $8, " #t0 "                      \n\t"\

        "movd -4" #src ", " #t1 "               \n\t"\

        "psrlq $24, " #t1 "                     \n\t"\

        "por " #t1 ", " #lx "                   \n\t" /* src[-1] */\

        "movd 8" #src ", " #t1 "                \n\t"\

        "psllq $56, " #t1 "                     \n\t"\

        "por " #t1 ", " #t0 "                   \n\t" /* src[+1] */\

        "movq " #lx ", " #t1 "                  \n\t" /* src[-1] */\

        PAVGB(t0, lx)                                 /* (src[-1] + src[+1])/2 */\

        PAVGB(sx, lx)                                 /* (src[-1] + 2src[0] + src[+1])/4 */\

        PAVGB(lx, pplx)                                     \

        "movq " #lx ", 8(%4)                    \n\t"\

        "movq (%4), " #lx "                     \n\t"\

        "psubusb " #lx ", " #t1 "               \n\t"\

        "psubusb " #lx ", " #t0 "               \n\t"\

        "psubusb " #lx ", " #sx "               \n\t"\

        "movq "MANGLE(b00)", " #lx "            \n\t"\

        "pcmpeqb " #lx ", " #t1 "               \n\t" /* src[-1] > a ? 0 : -1*/\

        "pcmpeqb " #lx ", " #t0 "               \n\t" /* src[+1] > a ? 0 : -1*/\

        "pcmpeqb " #lx ", " #sx "               \n\t" /* src[0]  > a ? 0 : -1*/\

        "paddb " #t1 ", " #t0 "                 \n\t"\

        "paddb " #t0 ", " #sx "                 \n\t"\

\

        PAVGB(plx, pplx)                              /* filtered */\

        "movq " #dst ", " #t0 "                 \n\t" /* dst */\

        "movq " #t0 ", " #t1 "                  \n\t" /* dst */\

        "psubusb %3, " #t0 "                    \n\t"\

        "paddusb %3, " #t1 "                    \n\t"\

        PMAXUB(t0, pplx)\

        PMINUB(t1, pplx, t0)\

        "paddb " #sx ", " #ppsx "               \n\t"\

        "paddb " #psx ", " #ppsx "              \n\t"\

        "#paddb "MANGLE(b02)", " #ppsx "        \n\t"\

        "pand "MANGLE(b08)", " #ppsx "          \n\t"\

        "pcmpeqb " #lx ", " #ppsx "             \n\t"\

        "pand " #ppsx ", " #pplx "              \n\t"\

        "pandn " #dst ", " #ppsx "              \n\t"\

        "por " #pplx ", " #ppsx "               \n\t"\

        "movq " #ppsx ", " #dst "               \n\t"\

        "movq 8(%4), " #lx "                    \n\t"



#define DERING_CORE(dst,src,ppsx,psx,sx,pplx,plx,lx,t0,t1) \

   REAL_DERING_CORE(dst,src,ppsx,psx,sx,pplx,plx,lx,t0,t1)

/*

0000000

1111111



1111110

1111101

1111100

1111011

1111010

1111001



1111000

1110111



*/

//DERING_CORE(dst          ,src            ,ppsx ,psx  ,sx   ,pplx ,plx  ,lx   ,t0   ,t1)

DERING_CORE((%%REGa)       ,(%%REGa, %1)   ,%%mm0,%%mm2,%%mm4,%%mm1,%%mm3,%%mm5,%%mm6,%%mm7)

DERING_CORE((%%REGa, %1)   ,(%%REGa, %1, 2),%%mm2,%%mm4,%%mm0,%%mm3,%%mm5,%%mm1,%%mm6,%%mm7)

DERING_CORE((%%REGa, %1, 2),(%0, %1, 4)    ,%%mm4,%%mm0,%%mm2,%%mm5,%%mm1,%%mm3,%%mm6,%%mm7)

DERING_CORE((%0, %1, 4)    ,(%%REGd)       ,%%mm0,%%mm2,%%mm4,%%mm1,%%mm3,%%mm5,%%mm6,%%mm7)

DERING_CORE((%%REGd)       ,(%%REGd, %1)   ,%%mm2,%%mm4,%%mm0,%%mm3,%%mm5,%%mm1,%%mm6,%%mm7)

DERING_CORE((%%REGd, %1)   ,(%%REGd, %1, 2),%%mm4,%%mm0,%%mm2,%%mm5,%%mm1,%%mm3,%%mm6,%%mm7)

DERING_CORE((%%REGd, %1, 2),(%0, %1, 8)    ,%%mm0,%%mm2,%%mm4,%%mm1,%%mm3,%%mm5,%%mm6,%%mm7)

DERING_CORE((%0, %1, 8)    ,(%%REGd, %1, 4),%%mm2,%%mm4,%%mm0,%%mm3,%%mm5,%%mm1,%%mm6,%%mm7)



        "1:                        \n\t"

        : : "r" (src), "r" ((x86_reg)stride), "m" (c->pQPb), "m"(c->pQPb2), "q"(tmp)

        : "%"REG_a, "%"REG_d

    );

#else // HAVE_7REGS && (TEMPLATE_PP_MMXEXT || TEMPLATE_PP_3DNOW)

    int y;

    int min=255;

    int max=0;

    int avg;

    uint8_t *p;

    int s[10];

    const int QP2= c->QP/2 + 1;



    src --;

    for(y=1; y<9; y++){

        int x;

        p= src + stride*y;

        for(x=1; x<9; x++){

            p++;

            if(*p > max) max= *p;

            if(*p < min) min= *p;

        }

    }

    avg= (min + max + 1)>>1;



    if(max - min <deringThreshold) return;



    for(y=0; y<10; y++){

        int t = 0;



        if(src[stride*y + 0] > avg) t+= 1;

        if(src[stride*y + 1] > avg) t+= 2;

        if(src[stride*y + 2] > avg) t+= 4;

        if(src[stride*y + 3] > avg) t+= 8;

        if(src[stride*y + 4] > avg) t+= 16;

        if(src[stride*y + 5] > avg) t+= 32;

        if(src[stride*y + 6] > avg) t+= 64;

        if(src[stride*y + 7] > avg) t+= 128;

        if(src[stride*y + 8] > avg) t+= 256;

        if(src[stride*y + 9] > avg) t+= 512;



        t |= (~t)<<16;

        t &= (t<<1) & (t>>1);

        s[y] = t;

    }



    for(y=1; y<9; y++){

        int t = s[y-1] & s[y] & s[y+1];

        t|= t>>16;

        s[y-1]= t;

    }



    for(y=1; y<9; y++){

        int x;

        int t = s[y-1];



        p= src + stride*y;

        for(x=1; x<9; x++){

            p++;

            if(t & (1<<x)){

                int f= (*(p-stride-1)) + 2*(*(p-stride)) + (*(p-stride+1))

                      +2*(*(p     -1)) + 4*(*p         ) + 2*(*(p     +1))

                      +(*(p+stride-1)) + 2*(*(p+stride)) + (*(p+stride+1));

                f= (f + 8)>>4;



#ifdef DEBUG_DERING_THRESHOLD

                    __asm__ volatile("emms\n\t":);

                    {

                    static long long numPixels=0;

                    if(x!=1 && x!=8 && y!=1 && y!=8) numPixels++;

//                    if((max-min)<20 || (max-min)*QP<200)

//                    if((max-min)*QP < 500)

//                    if(max-min<QP/2)

                    if(max-min < 20){

                        static int numSkipped=0;

                        static int errorSum=0;

                        static int worstQP=0;

                        static int worstRange=0;

                        static int worstDiff=0;

                        int diff= (f - *p);

                        int absDiff= FFABS(diff);

                        int error= diff*diff;



                        if(x==1 || x==8 || y==1 || y==8) continue;



                        numSkipped++;

                        if(absDiff > worstDiff){

                            worstDiff= absDiff;

                            worstQP= QP;

                            worstRange= max-min;

                        }

                        errorSum+= error;



                        if(1024LL*1024LL*1024LL % numSkipped == 0){

                            av_log(c, AV_LOG_INFO, "sum:%1.3f, skip:%d, wQP:%d, "

                                   "wRange:%d, wDiff:%d, relSkip:%1.3f\n",

                                   (float)errorSum/numSkipped, numSkipped, worstQP, worstRange,

                                   worstDiff, (float)numSkipped/numPixels);

                        }

                    }

                    }

#endif

                    if     (*p + QP2 < f) *p= *p + QP2;

                    else if(*p - QP2 > f) *p= *p - QP2;

                    else *p=f;

            }

        }

    }

#ifdef DEBUG_DERING_THRESHOLD

    if(max-min < 20){

        for(y=1; y<9; y++){

            int x;

            int t = 0;

            p= src + stride*y;

            for(x=1; x<9; x++){

                p++;

                *p = FFMIN(*p + 20, 255);

            }

        }

//        src[0] = src[7]=src[stride*7]=src[stride*7 + 7]=255;

    }

#endif

#endif //TEMPLATE_PP_MMXEXT || TEMPLATE_PP_3DNOW

}

static void RENAME(uyvytoyuv422)(uint8_t *ydst, uint8_t *udst, uint8_t *vdst, const uint8_t *src,

                                      long width, long height,

                                      long lumStride, long chromStride, long srcStride)

{

    long y;

    const long chromWidth= -((-width)>>1);



    for (y=0; y<height; y++) {

        RENAME(extract_even)(src+1, ydst, width);

        RENAME(extract_even2)(src, udst, vdst, chromWidth);



        src += srcStride;

        ydst+= lumStride;

        udst+= chromStride;

        vdst+= chromStride;

    }

#if COMPILE_TEMPLATE_MMX

    __asm__(

            EMMS"       \n\t"

            SFENCE"     \n\t"

            ::: "memory"

        );

#endif

}

static inline void RENAME(rgb24to15)(const uint8_t *src, uint8_t *dst, long src_size)

{

	const uint8_t *s = src;

	const uint8_t *end;

#ifdef HAVE_MMX

	const uint8_t *mm_end;

#endif

	uint16_t *d = (uint16_t *)dst;

	end = s + src_size;

#ifdef HAVE_MMX

	__asm __volatile(PREFETCH"	%0"::"m"(*src):"memory");

	__asm __volatile(

	    "movq	%0, %%mm7\n\t"

	    "movq	%1, %%mm6\n\t"

	    ::"m"(red_15mask),"m"(green_15mask));

	mm_end = end - 11;

	while(s < mm_end)

	{

	    __asm __volatile(

		PREFETCH" 32%1\n\t"

		"movd	%1, %%mm0\n\t"

		"movd	3%1, %%mm3\n\t"

		"punpckldq 6%1, %%mm0\n\t"

		"punpckldq 9%1, %%mm3\n\t"

		"movq	%%mm0, %%mm1\n\t"

		"movq	%%mm0, %%mm2\n\t"

		"movq	%%mm3, %%mm4\n\t"

		"movq	%%mm3, %%mm5\n\t"

		"psrlq	$3, %%mm0\n\t"

		"psrlq	$3, %%mm3\n\t"

		"pand	%2, %%mm0\n\t"

		"pand	%2, %%mm3\n\t"

		"psrlq	$6, %%mm1\n\t"

		"psrlq	$6, %%mm4\n\t"

		"pand	%%mm6, %%mm1\n\t"

		"pand	%%mm6, %%mm4\n\t"

		"psrlq	$9, %%mm2\n\t"

		"psrlq	$9, %%mm5\n\t"

		"pand	%%mm7, %%mm2\n\t"

		"pand	%%mm7, %%mm5\n\t"

		"por	%%mm1, %%mm0\n\t"

		"por	%%mm4, %%mm3\n\t"

		"por	%%mm2, %%mm0\n\t"

		"por	%%mm5, %%mm3\n\t"

		"psllq	$16, %%mm3\n\t"

		"por	%%mm3, %%mm0\n\t"

		MOVNTQ"	%%mm0, %0\n\t"

		:"=m"(*d):"m"(*s),"m"(blue_15mask):"memory");

		d += 4;

		s += 12;

	}

	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#endif

	while(s < end)

	{

		const int b= *s++;

		const int g= *s++;

		const int r= *s++;

		*d++ = (b>>3) | ((g&0xF8)<<2) | ((r&0xF8)<<7);

	}

}

static inline void RENAME(uyvyToY)(uint8_t *dst, uint8_t *src, int width)

{

#ifdef HAVE_MMX

	asm volatile(

		"mov %0, %%"REG_a"		\n\t"

		"1:				\n\t"

		"movq (%1, %%"REG_a",2), %%mm0	\n\t"

		"movq 8(%1, %%"REG_a",2), %%mm1	\n\t"

		"psrlw $8, %%mm0		\n\t"

		"psrlw $8, %%mm1		\n\t"

		"packuswb %%mm1, %%mm0		\n\t"

		"movq %%mm0, (%2, %%"REG_a")	\n\t"

		"add $8, %%"REG_a"		\n\t"

		" js 1b				\n\t"

		: : "g" ((long)-width), "r" (src+width*2), "r" (dst+width)

		: "%"REG_a

	);

#else

	int i;

	for(i=0; i<width; i++)

		dst[i]= src[2*i+1];

#endif

}

static inline void RENAME(yuvPlanartouyvy)(const uint8_t *ysrc, const uint8_t *usrc, const uint8_t *vsrc, uint8_t *dst,

	long width, long height,

	long lumStride, long chromStride, long dstStride, long vertLumPerChroma)

{

	long y;

	const long chromWidth= width>>1;

	for(y=0; y<height; y++)

	{

#ifdef HAVE_MMX

//FIXME handle 2 lines a once (fewer prefetch, reuse some chrom, but very likely limited by mem anyway)

		asm volatile(

			"xor %%"REG_a", %%"REG_a"	\n\t"

			ASMALIGN16

			"1:				\n\t"

			PREFETCH" 32(%1, %%"REG_a", 2)	\n\t"

			PREFETCH" 32(%2, %%"REG_a")	\n\t"

			PREFETCH" 32(%3, %%"REG_a")	\n\t"

			"movq (%2, %%"REG_a"), %%mm0	\n\t" // U(0)

			"movq %%mm0, %%mm2		\n\t" // U(0)

			"movq (%3, %%"REG_a"), %%mm1	\n\t" // V(0)

			"punpcklbw %%mm1, %%mm0		\n\t" // UVUV UVUV(0)

			"punpckhbw %%mm1, %%mm2		\n\t" // UVUV UVUV(8)



			"movq (%1, %%"REG_a",2), %%mm3	\n\t" // Y(0)

			"movq 8(%1, %%"REG_a",2), %%mm5	\n\t" // Y(8)

			"movq %%mm0, %%mm4		\n\t" // Y(0)

			"movq %%mm2, %%mm6		\n\t" // Y(8)

			"punpcklbw %%mm3, %%mm0		\n\t" // YUYV YUYV(0)

			"punpckhbw %%mm3, %%mm4		\n\t" // YUYV YUYV(4)

			"punpcklbw %%mm5, %%mm2		\n\t" // YUYV YUYV(8)

			"punpckhbw %%mm5, %%mm6		\n\t" // YUYV YUYV(12)



			MOVNTQ" %%mm0, (%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm4, 8(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm2, 16(%0, %%"REG_a", 4)\n\t"

			MOVNTQ" %%mm6, 24(%0, %%"REG_a", 4)\n\t"



			"add $8, %%"REG_a"		\n\t"

			"cmp %4, %%"REG_a"		\n\t"

			" jb 1b				\n\t"

			::"r"(dst), "r"(ysrc), "r"(usrc), "r"(vsrc), "g" (chromWidth)

			: "%"REG_a

		);

#else

//FIXME adapt the alpha asm code from yv12->yuy2



#if __WORDSIZE >= 64

		int i;

		uint64_t *ldst = (uint64_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i += 2){

			uint64_t k, l;

			k = uc[0] + (yc[0] << 8) +

			    (vc[0] << 16) + (yc[1] << 24);

			l = uc[1] + (yc[2] << 8) +

			    (vc[1] << 16) + (yc[3] << 24);

			*ldst++ = k + (l << 32);

			yc += 4;

			uc += 2;

			vc += 2;

		}



#else

		int i, *idst = (int32_t *) dst;

		const uint8_t *yc = ysrc, *uc = usrc, *vc = vsrc;

		for(i = 0; i < chromWidth; i++){

#ifdef WORDS_BIGENDIAN

			*idst++ = (uc[0] << 24)+ (yc[0] << 16) +

			    (vc[0] << 8) + (yc[1] << 0);

#else

			*idst++ = uc[0] + (yc[0] << 8) +

			    (vc[0] << 16) + (yc[1] << 24);

#endif

			yc += 2;

			uc++;

			vc++;

		}

