                    case PIX_FMT_YUYV422: c->yuv2packedX = RENAME(yuv2yuyv422_X); break;

                    default: break;

                    }

                }

            }

        }

        if (!(c->flags & SWS_FULL_CHR_H_INT)) {

            switch (c->dstFormat) {

