static void RENAME(extract_odd2)(const uint8_t *src, uint8_t *dst0, uint8_t *dst1, x86_reg count)

{

    dst0+=   count;

    dst1+=   count;

    src += 4*count;

    count= - count;

#if COMPILE_TEMPLATE_MMX

    if(count <= -8) {

        count += 7;

        __asm__ volatile(

            "pcmpeqw       %%mm7, %%mm7        \n\t"

            "psrlw            $8, %%mm7        \n\t"

            "1:                                \n\t"

            "movq -28(%1, %0, 4), %%mm0        \n\t"

            "movq -20(%1, %0, 4), %%mm1        \n\t"

            "movq -12(%1, %0, 4), %%mm2        \n\t"

            "movq  -4(%1, %0, 4), %%mm3        \n\t"

            "psrlw            $8, %%mm0        \n\t"

            "psrlw            $8, %%mm1        \n\t"

            "psrlw            $8, %%mm2        \n\t"

            "psrlw            $8, %%mm3        \n\t"

            "packuswb      %%mm1, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm2        \n\t"

            "movq          %%mm0, %%mm1        \n\t"

            "movq          %%mm2, %%mm3        \n\t"

            "psrlw            $8, %%mm0        \n\t"

            "psrlw            $8, %%mm2        \n\t"

            "pand          %%mm7, %%mm1        \n\t"

            "pand          %%mm7, %%mm3        \n\t"

            "packuswb      %%mm2, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm1        \n\t"

            MOVNTQ"        %%mm0,- 7(%3, %0)   \n\t"

            MOVNTQ"        %%mm1,- 7(%2, %0)   \n\t"

            "add              $8, %0           \n\t"

            " js 1b                            \n\t"

            : "+r"(count)

            : "r"(src), "r"(dst0), "r"(dst1)

        );

        count -= 7;

    }

#endif

    src++;

    while(count<0) {

        dst0[count]= src[4*count+0];

        dst1[count]= src[4*count+2];

        count++;

    }

}

static void RENAME(lumRangeToJpeg)(int16_t *dst, int width)

{

    int i;

    for (i = 0; i < width; i++)

        dst[i] = (FFMIN(dst[i],30189)*19077 - 39057361)>>14;

}

static inline void RENAME(yuv2yuv1)(SwsContext *c, const int16_t *lumSrc, const int16_t *chrSrc, const int16_t *alpSrc,

                                    uint8_t *dest, uint8_t *uDest, uint8_t *vDest, uint8_t *aDest, int dstW, int chrDstW)

{

    int i;

#if COMPILE_TEMPLATE_MMX

    if(!(c->flags & SWS_BITEXACT)) {

        long p= 4;

        const uint8_t *src[4]= {alpSrc + dstW, lumSrc + dstW, chrSrc + chrDstW, chrSrc + VOFW + chrDstW};

        uint8_t *dst[4]= {aDest, dest, uDest, vDest};

        x86_reg counter[4]= {dstW, dstW, chrDstW, chrDstW};



        if (c->flags & SWS_ACCURATE_RND) {

            while(p--) {

                if (dst[p]) {

                    __asm__ volatile(

                        YSCALEYUV2YV121_ACCURATE

                        :: "r" (src[p]), "r" (dst[p] + counter[p]),

                        "g" (-counter[p])

                        : "%"REG_a

                    );

                }

            }

        } else {

            while(p--) {

                if (dst[p]) {

                    __asm__ volatile(

                        YSCALEYUV2YV121

                        :: "r" (src[p]), "r" (dst[p] + counter[p]),

                        "g" (-counter[p])

                        : "%"REG_a

                    );

                }

            }

        }

        return;

    }

#endif

    for (i=0; i<dstW; i++) {

        int val= (lumSrc[i]+64)>>7;



        if (val&256) {

            if (val<0) val=0;

            else       val=255;

        }



        dest[i]= val;

    }



    if (uDest)

        for (i=0; i<chrDstW; i++) {

            int u=(chrSrc[i       ]+64)>>7;

            int v=(chrSrc[i + VOFW]+64)>>7;



            if ((u|v)&256) {

                if (u<0)        u=0;

                else if (u>255) u=255;

                if (v<0)        v=0;

                else if (v>255) v=255;

            }



            uDest[i]= u;

            vDest[i]= v;

        }



    if (CONFIG_SWSCALE_ALPHA && aDest)

        for (i=0; i<dstW; i++) {

            int val= (alpSrc[i]+64)>>7;

            aDest[i]= av_clip_uint8(val);

        }

}

static inline void RENAME(bgr24ToUV_half)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, long width, uint32_t *unused)

{

    int i;

    for (i=0; i<width; i++) {

        int b= src1[6*i + 0] + src1[6*i + 3];

        int g= src1[6*i + 1] + src1[6*i + 4];

        int r= src1[6*i + 2] + src1[6*i + 5];



        dstU[i]= (RU*r + GU*g + BU*b + (257<<RGB2YUV_SHIFT))>>(RGB2YUV_SHIFT+1);

        dstV[i]= (RV*r + GV*g + BV*b + (257<<RGB2YUV_SHIFT))>>(RGB2YUV_SHIFT+1);

    }

    assert(src1 == src2);

}

static inline void RENAME(rgb16to15)(const uint8_t *src,uint8_t *dst,long src_size)

{

  register const uint8_t* s=src;

  register uint8_t* d=dst;

  register const uint8_t *end;

  const uint8_t *mm_end;

  end = s + src_size;

#ifdef HAVE_MMX

  __asm __volatile(PREFETCH"	%0"::"m"(*s));

