        default:

            goto cp0_unimplemented;

        }

        break;

    case 20:

        switch (sel) {

        case 0:

#if defined(TARGET_MIPS64)

            check_insn(ctx, ISA_MIPS3);

            gen_helper_mtc0_xcontext(cpu_env, arg);

            rn = "XContext";

            break;

#endif

        default:

            goto cp0_unimplemented;

        }

        break;

    case 21:

       /* Officially reserved, but sel 0 is used for R1x000 framemask */

        CP0_CHECK(!(ctx->insn_flags & ISA_MIPS32R6));

        switch (sel) {

        case 0:

            gen_helper_mtc0_framemask(cpu_env, arg);

            rn = "Framemask";

            break;

        default:

            goto cp0_unimplemented;

        }

        break;

    case 22:

        /* ignored */

        rn = "Diagnostic"; /* implementation dependent */

        break;

    case 23:

        switch (sel) {

        case 0:

            gen_helper_mtc0_debug(cpu_env, arg); /* EJTAG support */

            /* BS_STOP isn't good enough here, hflags may have changed. */

            gen_save_pc(ctx->pc + 4);

            ctx->bstate = BS_EXCP;

            rn = "Debug";

            break;

        case 1:

//            gen_helper_mtc0_tracecontrol(cpu_env, arg); /* PDtrace support */

            rn = "TraceControl";

            /* Stop translation as we may have switched the execution mode */

            ctx->bstate = BS_STOP;

//            break;

        case 2:

//            gen_helper_mtc0_tracecontrol2(cpu_env, arg); /* PDtrace support */

            rn = "TraceControl2";

            /* Stop translation as we may have switched the execution mode */

            ctx->bstate = BS_STOP;

//            break;

        case 3:

            /* Stop translation as we may have switched the execution mode */

            ctx->bstate = BS_STOP;

//            gen_helper_mtc0_usertracedata(cpu_env, arg); /* PDtrace support */

            rn = "UserTraceData";

            /* Stop translation as we may have switched the execution mode */

            ctx->bstate = BS_STOP;

//            break;

        case 4:

//            gen_helper_mtc0_tracebpc(cpu_env, arg); /* PDtrace support */

            /* Stop translation as we may have switched the execution mode */

            ctx->bstate = BS_STOP;

            rn = "TraceBPC";

//            break;

        default:

            goto cp0_unimplemented;

        }

        break;

    case 24:

        switch (sel) {

        case 0:

            /* EJTAG support */

            gen_mtc0_store64(arg, offsetof(CPUMIPSState, CP0_DEPC));

            rn = "DEPC";

            break;

        default:

            goto cp0_unimplemented;

        }

        break;

    case 25:

        switch (sel) {

        case 0:

            gen_helper_mtc0_performance0(cpu_env, arg);

            rn = "Performance0";

            break;

        case 1:

//            gen_helper_mtc0_performance1(arg);

            rn = "Performance1";

//            break;

        case 2:

//            gen_helper_mtc0_performance2(arg);

            rn = "Performance2";

//            break;

        case 3:

//            gen_helper_mtc0_performance3(arg);

            rn = "Performance3";

//            break;

        case 4:

//            gen_helper_mtc0_performance4(arg);

            rn = "Performance4";

//            break;

        case 5:

//            gen_helper_mtc0_performance5(arg);

            rn = "Performance5";

//            break;

        case 6:

//            gen_helper_mtc0_performance6(arg);

            rn = "Performance6";

//            break;

        case 7:

//            gen_helper_mtc0_performance7(arg);

            rn = "Performance7";

//            break;

        default:

            goto cp0_unimplemented;

        }

       break;

    case 26:

        /* ignored */

        rn = "ECC";

        break;

    case 27:

        switch (sel) {

        case 0 ... 3:

            /* ignored */

            rn = "CacheErr";

            break;

        default:

            goto cp0_unimplemented;

        }

       break;

    case 28:

        switch (sel) {

        case 0:

        case 2:

        case 4:

        case 6:

            gen_helper_mtc0_taglo(cpu_env, arg);

            rn = "TagLo";

            break;

        case 1:

        case 3:

        case 5:

        case 7:

            gen_helper_mtc0_datalo(cpu_env, arg);

            rn = "DataLo";

            break;

        default:

            goto cp0_unimplemented;

        }

        break;

    case 29:

        switch (sel) {

        case 0:

        case 2:

        case 4:

        case 6:

            gen_helper_mtc0_taghi(cpu_env, arg);

            rn = "TagHi";

            break;

        case 1:

        case 3:

        case 5:

        case 7:

            gen_helper_mtc0_datahi(cpu_env, arg);

            rn = "DataHi";

            break;

        default:

            rn = "invalid sel";

            goto cp0_unimplemented;

        }

       break;

    case 30:

        switch (sel) {

        case 0:

            gen_mtc0_store64(arg, offsetof(CPUMIPSState, CP0_ErrorEPC));

            rn = "ErrorEPC";

            break;

        default:

            goto cp0_unimplemented;

        }

        break;

    case 31:

        switch (sel) {

        case 0:

            /* EJTAG support */

            gen_mtc0_store32(arg, offsetof(CPUMIPSState, CP0_DESAVE));

            rn = "DESAVE";

            break;

        case 2 ... 7:

            CP0_CHECK(ctx->kscrexist & (1 << sel));

            tcg_gen_st_tl(arg, cpu_env,

                          offsetof(CPUMIPSState, CP0_KScratch[sel-2]));

            rn = "KScratch";

            break;

        default:

            goto cp0_unimplemented;

        }

        /* Stop translation as we may have switched the execution mode */

        ctx->bstate = BS_STOP;

        break;

    default:

       goto cp0_unimplemented;

    }

    (void)rn; /* avoid a compiler warning */

    LOG_DISAS("mtc0 %s (reg %d sel %d)\n", rn, reg, sel);

    /* For simplicity assume that all writes can cause interrupts.  */

    if (use_icount) {

        gen_io_end();

        ctx->bstate = BS_STOP;

    }

    return;



cp0_unimplemented:

    LOG_DISAS("mtc0 %s (reg %d sel %d)\n", rn, reg, sel);

}

decode_motion_vector.code:
static int decode_motion_vector (bit_buffer_t *bitbuf, svq1_pmv_t *mv, svq1_pmv_t **pmv) {

  uint32_t    bit_cache;

  vlc_code_t *vlc;

  int	      diff, sign;

  int	      i;



  for (i=0; i < 2; i++) {



    /* get motion code */

    bit_cache = get_bit_cache (bitbuf);



    if (!(bit_cache & 0xFFE00000))

      return -1;	/* invalid vlc code */



    if (bit_cache & 0x80000000) {

      diff = 0;



      /* flush bit */

      skip_bits(bitbuf,1);



    } else {

      if (bit_cache >= 0x06000000) {

        vlc = &motion_table_0[(bit_cache >> (32 - 7)) - 3];

      } else {

        vlc = &motion_table_1[(bit_cache >> (32 - 12)) - 2];

      }



      /* decode motion vector differential */

      sign = (int) (bit_cache << (vlc->length - 1)) >> 31;

      diff = (vlc->value ^ sign) - sign;



      /* flush bits */

      skip_bits(bitbuf,vlc->length);

    }



    /* add median of motion vector predictors and clip result */

    if (i == 1)

      mv->y = ((diff + MEDIAN(pmv[0]->y, pmv[1]->y, pmv[2]->y)) << 26) >> 26;

    else

      mv->x = ((diff + MEDIAN(pmv[0]->x, pmv[1]->x, pmv[2]->x)) << 26) >> 26;

  }



  return 0;

}

verify_md5.code:
static int verify_md5(HEVCContext *s, AVFrame *frame)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(frame->format);

    int pixel_shift = desc->comp[0].depth_minus1 > 7;

    int i, j;



    if (!desc)

        return AVERROR(EINVAL);



    av_log(s->avctx, AV_LOG_DEBUG, "Verifying checksum for frame with POC %d: ",

           s->poc);



    /* the checksums are LE, so we have to byteswap for >8bpp formats

     * on BE arches */

#if HAVE_BIGENDIAN

    if (pixel_shift && !s->checksum_buf) {

        av_fast_malloc(&s->checksum_buf, &s->checksum_buf_size,

                       FFMAX3(frame->linesize[0], frame->linesize[1],

                              frame->linesize[2]));

        if (!s->checksum_buf)

            return AVERROR(ENOMEM);

    }

#endif



    for (i = 0; frame->data[i]; i++) {

        int width  = s->avctx->coded_width;

        int height = s->avctx->coded_height;

        int w = (i == 1 || i == 2) ? (width  >> desc->log2_chroma_w) : width;

        int h = (i == 1 || i == 2) ? (height >> desc->log2_chroma_h) : height;

        uint8_t md5[16];



        av_md5_init(s->md5_ctx);

        for (j = 0; j < h; j++) {

            const uint8_t *src = frame->data[i] + j * frame->linesize[i];

#if HAVE_BIGENDIAN

            if (pixel_shift) {

                s->dsp.bswap16_buf((uint16_t*)s->checksum_buf,

                                   (const uint16_t*)src, w);

                src = s->checksum_buf;

            }

#endif

            av_md5_update(s->md5_ctx, src, w << pixel_shift);

        }

        av_md5_final(s->md5_ctx, md5);



        if (!memcmp(md5, s->md5[i], 16)) {

            av_log   (s->avctx, AV_LOG_DEBUG, "plane %d - correct ", i);

            print_md5(s->avctx, AV_LOG_DEBUG, md5);

            av_log   (s->avctx, AV_LOG_DEBUG, "; ");

        } else {

            av_log   (s->avctx, AV_LOG_ERROR, "mismatching checksum of plane %d - ", i);

            print_md5(s->avctx, AV_LOG_ERROR, md5);

            av_log   (s->avctx, AV_LOG_ERROR, " != ");

            print_md5(s->avctx, AV_LOG_ERROR, s->md5[i]);

            av_log   (s->avctx, AV_LOG_ERROR, "\n");

            return AVERROR_INVALIDDATA;

        }

    }



    av_log(s->avctx, AV_LOG_DEBUG, "\n");



    return 0;

}

read_seek.code:
static int read_seek(AVFormatContext *s, int stream_index, int64_t timestamp, int flags)

{

    BinkDemuxContext *bink = s->priv_data;

    AVStream *vst = s->streams[0];



    if (!s->pb->seekable)

        return -1;



    /* seek to the first frame */

    if (avio_seek(s->pb, vst->index_entries[0].pos, SEEK_SET) < 0)

        return -1;



    bink->video_pts = 0;

    memset(bink->audio_pts, 0, sizeof(bink->audio_pts));

    bink->current_track = -1;

    return 0;

}

static int read_seek(AVFormatContext *s, int stream_index,

                     int64_t timestamp, int flags)

{

    AVStream *st = s->streams[0];

    CaffContext *caf = s->priv_data;

    int64_t pos;



    timestamp = FFMAX(timestamp, 0);



    if (caf->frames_per_packet > 0 && caf->bytes_per_packet > 0) {

        /* calculate new byte position based on target frame position */

        pos = caf->bytes_per_packet * timestamp / caf->frames_per_packet;

        if (caf->data_size > 0)

            pos = FFMIN(pos, caf->data_size);

        caf->packet_cnt = pos / caf->bytes_per_packet;

        caf->frame_cnt  = caf->frames_per_packet * caf->packet_cnt;

    } else if (st->nb_index_entries) {

        caf->packet_cnt = av_index_search_timestamp(st, timestamp, flags);

        caf->frame_cnt  = st->index_entries[caf->packet_cnt].timestamp;

        pos             = st->index_entries[caf->packet_cnt].pos;

    } else {

        return -1;

    }



    avio_seek(s->pb, pos + caf->data_start, SEEK_SET);

    return 0;

}

static int read_seek(AVFormatContext *s, int stream_index,

                     int64_t ts, int flags)

{

    WtvContext *wtv = s->priv_data;

    AVIOContext *pb = wtv->pb;

    AVStream *st = s->streams[0];

    int64_t ts_relative;

    int i;



    if ((flags & AVSEEK_FLAG_FRAME) || (flags & AVSEEK_FLAG_BYTE))

        return AVERROR(ENOSYS);



    /* timestamp adjustment is required because wtv->pts values are absolute,

     * whereas AVIndexEntry->timestamp values are relative to epoch. */

    ts_relative = ts;

    if (wtv->epoch != AV_NOPTS_VALUE)

        ts_relative -= wtv->epoch;



    i = ff_index_search_timestamp(wtv->index_entries, wtv->nb_index_entries, ts_relative, flags);

    if (i < 0) {

        if (wtv->last_valid_pts == AV_NOPTS_VALUE || ts < wtv->last_valid_pts)

            avio_seek(pb, 0, SEEK_SET);

        else if (st->duration != AV_NOPTS_VALUE && ts_relative > st->duration && wtv->nb_index_entries)

            avio_seek(pb, wtv->index_entries[wtv->nb_index_entries - 1].pos, SEEK_SET);

        if (parse_chunks(s, SEEK_TO_PTS, ts, 0) < 0)

            return AVERROR(ERANGE);

        return 0;

    }

    wtv->pts = wtv->index_entries[i].timestamp;

    if (wtv->epoch != AV_NOPTS_VALUE)

        wtv->pts += wtv->epoch;

    wtv->last_valid_pts = wtv->pts;

    avio_seek(pb, wtv->index_entries[i].pos, SEEK_SET);

    return 0;

}

static int read_seek(AVFormatContext *s, int stream_index, int64_t timestamp, int flags)

{

    AVStream *st = s->streams[stream_index];

    avio_seek(s->pb, FFMAX(timestamp, 0) * st->codec->width * st->codec->height * 4, SEEK_SET);

    return 0;

}

static int read_seek(AVFormatContext *s, int stream_index,

                     int64_t pts, int flags)

{

    NUTContext *nut    = s->priv_data;

    AVStream *st       = s->streams[stream_index];

    Syncpoint dummy    = { .ts = pts * av_q2d(st->time_base) * AV_TIME_BASE };

    Syncpoint nopts_sp = { .ts = AV_NOPTS_VALUE, .back_ptr = AV_NOPTS_VALUE };

    Syncpoint *sp, *next_node[2] = { &nopts_sp, &nopts_sp };

    int64_t pos, pos2, ts;

    int i;



    if (nut->flags & NUT_PIPE) {

        return AVERROR(ENOSYS);

    }



    if (st->index_entries) {

        int index = av_index_search_timestamp(st, pts, flags);

        if (index < 0)

            index = av_index_search_timestamp(st, pts, flags ^ AVSEEK_FLAG_BACKWARD);

        if (index < 0)

            return -1;



        pos2 = st->index_entries[index].pos;

        ts   = st->index_entries[index].timestamp;

    } else {

        av_tree_find(nut->syncpoints, &dummy, (void *) ff_nut_sp_pts_cmp,

                     (void **) next_node);

        av_log(s, AV_LOG_DEBUG, "%"PRIu64"-%"PRIu64" %"PRId64"-%"PRId64"\n",

               next_node[0]->pos, next_node[1]->pos, next_node[0]->ts,

               next_node[1]->ts);

        pos = ff_gen_search(s, -1, dummy.ts, next_node[0]->pos,

                            next_node[1]->pos, next_node[1]->pos,

                            next_node[0]->ts, next_node[1]->ts,

                            AVSEEK_FLAG_BACKWARD, &ts, nut_read_timestamp);





        if (!(flags & AVSEEK_FLAG_BACKWARD)) {

            dummy.pos    = pos + 16;

            next_node[1] = &nopts_sp;

            av_tree_find(nut->syncpoints, &dummy, (void *) ff_nut_sp_pos_cmp,

                         (void **) next_node);

            pos2 = ff_gen_search(s, -2, dummy.pos, next_node[0]->pos,

                                 next_node[1]->pos, next_node[1]->pos,

                                 next_node[0]->back_ptr, next_node[1]->back_ptr,

                                 flags, &ts, nut_read_timestamp);

            if (pos2 >= 0)

                pos = pos2;

            // FIXME dir but I think it does not matter

        }

        dummy.pos = pos;

        sp = av_tree_find(nut->syncpoints, &dummy, (void *) ff_nut_sp_pos_cmp,

                          NULL);



        av_assert0(sp);

        pos2 = sp->back_ptr - 15;

    }

    av_log(NULL, AV_LOG_DEBUG, "SEEKTO: %"PRId64"\n", pos2);

    pos = find_startcode(s->pb, SYNCPOINT_STARTCODE, pos2);

    avio_seek(s->pb, pos, SEEK_SET);

    nut->last_syncpoint_pos = pos;

    av_log(NULL, AV_LOG_DEBUG, "SP: %"PRId64"\n", pos);

    if (pos2 > pos || pos2 + 15 < pos)

        av_log(NULL, AV_LOG_ERROR, "no syncpoint at backptr pos\n");

    for (i = 0; i < s->nb_streams; i++)

        nut->stream[i].skip_until_key_frame = 1;



    nut->last_resync_pos = 0;



    return 0;

}

