init_get_bits.code:
void init_get_bits(GetBitContext *s,

                   UINT8 *buffer, int buffer_size)

{

    s->buffer= buffer;

    s->size= buffer_size;

    s->buffer_end= buffer + buffer_size;

#ifdef ALT_BITSTREAM_READER

    s->index=0;

#elif defined LIBMPEG2_BITSTREAM_READER

    s->buffer_ptr = buffer;

    s->bit_count = 16;

    s->cache = 0;

#elif defined A32_BITSTREAM_READER

    s->buffer_ptr = (uint32_t*)buffer;

    s->bit_count = 32;

    s->cache0 = 0;

    s->cache1 = 0;

#endif

    {

        OPEN_READER(re, s)

        UPDATE_CACHE(re, s)

//        UPDATE_CACHE(re, s)

        CLOSE_READER(re, s)

    }

#ifdef A32_BITSTREAM_READER

    s->cache1 = 0;

#endif

}

avc_luma_hv_qrt_16w_msa.code:
static void avc_luma_hv_qrt_16w_msa(const uint8_t *src_x, const uint8_t *src_y,

                                    int32_t src_stride, uint8_t *dst,

                                    int32_t dst_stride, int32_t height)

{

    uint32_t multiple8_cnt;



    for (multiple8_cnt = 2; multiple8_cnt--;) {

        avc_luma_hv_qrt_8w_msa(src_x, src_y, src_stride, dst, dst_stride,

                               height);



        src_x += 8;

        src_y += 8;

        dst += 8;

    }

}

gen_goto_tb.code:
static inline void gen_goto_tb(DisasContext *ctx, int n, target_ulong dest)

{

    TranslationBlock *tb;

    tb = ctx->tb;

    if ((tb->pc & TARGET_PAGE_MASK) == (dest & TARGET_PAGE_MASK)) {

        if (n == 0)

            gen_op_goto_tb0(TBPARAM(tb));

        else

            gen_op_goto_tb1(TBPARAM(tb));

        gen_op_set_T1(dest);

        gen_op_b_T1();

        gen_op_set_T0((long)tb + n);

        if (ctx->singlestep_enabled)

            gen_op_debug();

        gen_op_exit_tb();

    } else {

        gen_op_set_T1(dest);

        gen_op_b_T1();

        gen_op_reset_T0();

        if (ctx->singlestep_enabled)

            gen_op_debug();

        gen_op_exit_tb();

    }

}

static inline void gen_goto_tb(DisasContext *s, int n, target_ulong dest)

{

    if (use_goto_tb(s, dest)) {

        tcg_gen_goto_tb(n);

        gen_set_pc_im(s, dest);

        tcg_gen_exit_tb((uintptr_t)s->tb + n);

    } else {

        TCGv addr = tcg_temp_new();



        gen_set_pc_im(s, dest);

        tcg_gen_extu_i32_tl(addr, cpu_R[15]);

        tcg_gen_lookup_and_goto_ptr(addr);

        tcg_temp_free(addr);

    }

}

static inline void gen_goto_tb(DisasContext *s, int tb_num, target_ulong eip)

{

    target_ulong pc = s->cs_base + eip;



    if (use_goto_tb(s, pc))  {

        /* jump to same page: we can use a direct jump */

        tcg_gen_goto_tb(tb_num);

        gen_jmp_im(eip);

        tcg_gen_exit_tb((uintptr_t)s->tb + tb_num);

    } else {

        /* jump to another page: currently not optimized */

        gen_jmp_im(eip);

        gen_eob(s);

    }

}

static inline void gen_goto_tb(DisasContext *s, int n, uint64_t dest)

{

    TranslationBlock *tb;



    tb = s->tb;

    if (use_goto_tb(s, n, dest)) {

        tcg_gen_goto_tb(n);

        gen_a64_set_pc_im(dest);

        tcg_gen_exit_tb((intptr_t)tb + n);

        s->is_jmp = DISAS_TB_JUMP;

    } else {

        gen_a64_set_pc_im(dest);

        if (s->singlestep_enabled) {

            gen_exception_internal(EXCP_DEBUG);

        }

        tcg_gen_exit_tb(0);

        s->is_jmp = DISAS_JUMP;

    }

}

hevc_decode_extradata.code:
static int hevc_decode_extradata(HEVCContext *s, uint8_t *buf, int length)

{

    int ret, i;



    ret = ff_hevc_decode_extradata(buf, length, &s->ps, &s->sei, &s->is_nalff,

                                   &s->nal_length_size, s->avctx->err_recognition,

                                   s->apply_defdispwin, s->avctx);

    if (ret < 0)

        return ret;



    /* export stream parameters from the first SPS */

    for (i = 0; i < FF_ARRAY_ELEMS(s->ps.sps_list); i++) {

        if (s->ps.sps_list[i]) {

            const HEVCSPS *sps = (const HEVCSPS*)s->ps.sps_list[i]->data;

            export_stream_params(s->avctx, &s->ps, sps);

            break;

        }

    }



    return 0;

}

