static int tta_get_unary(GetBitContext *gb)

{

    int ret = 0;



    // count ones

    while(get_bits1(gb))

        ret++;

    return ret;

}

ff_h264_decode_ref_pic_marking.code:
int ff_h264_decode_ref_pic_marking(H264Context *h, GetBitContext *gb,

                                   int first_slice)

{

    int i, ret;

    MMCO mmco_temp[MAX_MMCO_COUNT], *mmco = mmco_temp;

    int mmco_index = 0;



    if (h->nal_unit_type == NAL_IDR_SLICE) { // FIXME fields

        skip_bits1(gb); // broken_link

        if (get_bits1(gb)) {

            mmco[0].opcode   = MMCO_LONG;

            mmco[0].long_arg = 0;

            mmco_index       = 1;

        }

    } else {

        if (get_bits1(gb)) { // adaptive_ref_pic_marking_mode_flag

            for (i = 0; i < MAX_MMCO_COUNT; i++) {

                MMCOOpcode opcode = get_ue_golomb_31(gb);



                mmco[i].opcode = opcode;

                if (opcode == MMCO_SHORT2UNUSED || opcode == MMCO_SHORT2LONG) {

                    mmco[i].short_pic_num =

                        (h->curr_pic_num - get_ue_golomb(gb) - 1) &

                            (h->max_pic_num - 1);

#if 0

                    if (mmco[i].short_pic_num >= h->short_ref_count ||

                        !h->short_ref[mmco[i].short_pic_num]) {

                        av_log(s->avctx, AV_LOG_ERROR,

                               "illegal short ref in memory management control "

                               "operation %d\n", mmco);

                        return -1;

                    }

#endif

                }

                if (opcode == MMCO_SHORT2LONG || opcode == MMCO_LONG2UNUSED ||

                    opcode == MMCO_LONG || opcode == MMCO_SET_MAX_LONG) {

                    unsigned int long_arg = get_ue_golomb_31(gb);

                    if (long_arg >= 32 ||

                        (long_arg >= 16 && !(opcode == MMCO_SET_MAX_LONG &&

                                             long_arg == 16) &&

                         !(opcode == MMCO_LONG2UNUSED && FIELD_PICTURE(h)))) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "illegal long ref in memory management control "

                               "operation %d\n", opcode);

                        return -1;

                    }

                    mmco[i].long_arg = long_arg;

                }



                if (opcode > (unsigned) MMCO_LONG) {

                    av_log(h->avctx, AV_LOG_ERROR,

                           "illegal memory management control operation %d\n",

                           opcode);

                    return -1;

                }

                if (opcode == MMCO_END)

                    break;

            }

            mmco_index = i;

        } else {

            if (first_slice) {

                ret = ff_generate_sliding_window_mmcos(h, first_slice);

                if (ret < 0 && h->avctx->err_recognition & AV_EF_EXPLODE)

                    return ret;

            }

            mmco_index = -1;

        }

    }



    if (first_slice && mmco_index != -1) {

        memcpy(h->mmco, mmco_temp, sizeof(h->mmco));

        h->mmco_index = mmco_index;

    } else if (!first_slice && mmco_index >= 0 &&

               (mmco_index != h->mmco_index ||

                check_opcodes(h->mmco, mmco_temp, mmco_index))) {

        av_log(h->avctx, AV_LOG_ERROR,

               "Inconsistent MMCO state between slices [%d, %d]\n",

               mmco_index, h->mmco_index);

        return AVERROR_INVALIDDATA;

    }



    return 0;

}

int ff_h264_decode_ref_pic_marking(H264Context *h, GetBitContext *gb){

    MpegEncContext * const s = &h->s;

    int i;



    h->mmco_index= 0;

    if(h->nal_unit_type == NAL_IDR_SLICE){ //FIXME fields

        s->broken_link= get_bits1(gb) -1;

        if(get_bits1(gb)){

            h->mmco[0].opcode= MMCO_LONG;

            h->mmco[0].long_arg= 0;

            h->mmco_index= 1;

        }

    }else{

        if(get_bits1(gb)){ // adaptive_ref_pic_marking_mode_flag

            for(i= 0; i<MAX_MMCO_COUNT; i++) {

                MMCOOpcode opcode= get_ue_golomb_31(gb);



                h->mmco[i].opcode= opcode;

                if(opcode==MMCO_SHORT2UNUSED || opcode==MMCO_SHORT2LONG){

                    h->mmco[i].short_pic_num= (h->curr_pic_num - get_ue_golomb(gb) - 1) & (h->max_pic_num - 1);

/*                    if(h->mmco[i].short_pic_num >= h->short_ref_count || h->short_ref[ h->mmco[i].short_pic_num ] == NULL){

                        av_log(s->avctx, AV_LOG_ERROR, "illegal short ref in memory management control operation %d\n", mmco);

                        return -1;

                    }*/

                }

                if(opcode==MMCO_SHORT2LONG || opcode==MMCO_LONG2UNUSED || opcode==MMCO_LONG || opcode==MMCO_SET_MAX_LONG){

                    unsigned int long_arg= get_ue_golomb_31(gb);

                    if(long_arg >= 32 || (long_arg >= 16 && !(opcode == MMCO_LONG2UNUSED && FIELD_PICTURE))){

                        av_log(h->s.avctx, AV_LOG_ERROR, "illegal long ref in memory management control operation %d\n", opcode);

                        return -1;

                    }

                    h->mmco[i].long_arg= long_arg;

                }



                if(opcode > (unsigned)MMCO_LONG){

                    av_log(h->s.avctx, AV_LOG_ERROR, "illegal memory management control operation %d\n", opcode);

                    return -1;

                }

                if(opcode == MMCO_END)

                    break;

            }

            h->mmco_index= i;

        }else{

            ff_generate_sliding_window_mmcos(h);

        }

    }



    return 0;

}

lduw_phys_internal.code:
static inline uint32_t lduw_phys_internal(hwaddr addr,

                                          enum device_endian endian)

{

    uint8_t *ptr;

    uint64_t val;

    MemoryRegionSection *section;



    section = phys_page_find(address_space_memory.dispatch, addr >> TARGET_PAGE_BITS);



    if (!(memory_region_is_ram(section->mr) ||

          memory_region_is_romd(section->mr))) {

        /* I/O case */

        addr = memory_region_section_addr(section, addr);

        val = io_mem_read(section->mr, addr, 2);

#if defined(TARGET_WORDS_BIGENDIAN)

        if (endian == DEVICE_LITTLE_ENDIAN) {

            val = bswap16(val);

        }

#else

        if (endian == DEVICE_BIG_ENDIAN) {

            val = bswap16(val);

        }

#endif

    } else {

        /* RAM case */

        ptr = qemu_get_ram_ptr((memory_region_get_ram_addr(section->mr)

                                & TARGET_PAGE_MASK)

                               + memory_region_section_addr(section, addr));

        switch (endian) {

        case DEVICE_LITTLE_ENDIAN:

            val = lduw_le_p(ptr);

            break;

        case DEVICE_BIG_ENDIAN:

            val = lduw_be_p(ptr);

            break;

        default:

            val = lduw_p(ptr);

            break;

        }

    }

    return val;

}

get_bits.code:
static int get_bits(J2kDecoderContext *s, int n)

{

    int res = 0;

    if (s->buf_end - s->buf < ((n - s->bit_index) >> 8))

        return AVERROR(EINVAL);

    while (--n >= 0){

        res <<= 1;

        if (s->bit_index == 0){

            s->bit_index = 7 + (*s->buf != 0xff);

            s->buf++;

        }

        s->bit_index--;

        res |= (*s->buf >> s->bit_index) & 1;

    }

    return res;

}

static int get_bits(Jpeg2000DecoderContext *s, int n)

{

    int res = 0;

    if (s->buf_end - s->buf < ((n - s->bit_index) >> 8))

        return AVERROR(EINVAL);

    while (--n >= 0) {

        res <<= 1;

        if (s->bit_index == 0) {

            s->bit_index = 7 + (*s->buf != 0xff);

            s->buf++;

        }

        s->bit_index--;

        res |= (*s->buf >> s->bit_index) & 1;

    }

    return res;

}

ff_h264_decode_ref_pic_list_reordering.code:
int ff_h264_decode_ref_pic_list_reordering(H264Context *h, H264SliceContext *sl)

{

    int list, index, pic_structure;



    print_short_term(h);

    print_long_term(h);



    h264_initialise_ref_list(h, sl);



    for (list = 0; list < sl->list_count; list++) {

        if (get_bits1(&sl->gb)) {    // ref_pic_list_modification_flag_l[01]

            int pred = h->curr_pic_num;



            for (index = 0; ; index++) {

                unsigned int modification_of_pic_nums_idc = get_ue_golomb_31(&sl->gb);

                unsigned int pic_id;

                int i;

                H264Picture *ref = NULL;



                if (modification_of_pic_nums_idc == 3)

                    break;



                if (index >= sl->ref_count[list]) {

                    av_log(h->avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                switch (modification_of_pic_nums_idc) {

                case 0:

                case 1: {

                    const unsigned int abs_diff_pic_num = get_ue_golomb(&sl->gb) + 1;

                    int frame_num;



                    if (abs_diff_pic_num > h->max_pic_num) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "abs_diff_pic_num overflow\n");

                        return AVERROR_INVALIDDATA;

                    }



                    if (modification_of_pic_nums_idc == 0)

                        pred -= abs_diff_pic_num;

                    else

                        pred += abs_diff_pic_num;

                    pred &= h->max_pic_num - 1;



                    frame_num = pic_num_extract(h, pred, &pic_structure);



                    for (i = h->short_ref_count - 1; i >= 0; i--) {

                        ref = h->short_ref[i];

                        assert(ref->reference);

                        assert(!ref->long_ref);

                        if (ref->frame_num == frame_num &&

                            (ref->reference & pic_structure))

                            break;

                    }

                    if (i >= 0)

                        ref->pic_id = pred;

                    break;

                }

                case 2: {

                    int long_idx;

                    pic_id = get_ue_golomb(&sl->gb); // long_term_pic_idx



                    long_idx = pic_num_extract(h, pic_id, &pic_structure);



                    if (long_idx > 31) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "long_term_pic_idx overflow\n");

                        return AVERROR_INVALIDDATA;

                    }

                    ref = h->long_ref[long_idx];

                    assert(!(ref && !ref->reference));

                    if (ref && (ref->reference & pic_structure) && !mismatches_ref(h, ref)) {

                        ref->pic_id = pic_id;

                        assert(ref->long_ref);

                        i = 0;

                    } else {

                        i = -1;

                    }

                    break;

                }

                default:

                    av_log(h->avctx, AV_LOG_ERROR,

                           "illegal modification_of_pic_nums_idc %u\n",

                           modification_of_pic_nums_idc);

                    return AVERROR_INVALIDDATA;

                }



                if (i < 0) {

                    av_log(h->avctx, AV_LOG_ERROR,

                           "reference picture missing during reorder\n");

                    memset(&sl->ref_list[list][index], 0, sizeof(sl->ref_list[0][0])); // FIXME

                } else {

                    for (i = index; i + 1 < sl->ref_count[list]; i++) {

                        if (sl->ref_list[list][i].parent &&

                            ref->long_ref == sl->ref_list[list][i].parent->long_ref &&

                            ref->pic_id   == sl->ref_list[list][i].pic_id)

                            break;

                    }

                    for (; i > index; i--) {

                        sl->ref_list[list][i] = sl->ref_list[list][i - 1];

                    }

                    ref_from_h264pic(&sl->ref_list[list][index], ref);

                    if (FIELD_PICTURE(h)) {

                        pic_as_field(&sl->ref_list[list][index], pic_structure);

                    }

                }

            }

        }

    }

    for (list = 0; list < sl->list_count; list++) {

        for (index = 0; index < sl->ref_count[list]; index++) {

            if (   !sl->ref_list[list][index].parent

                || (!FIELD_PICTURE(h) && (sl->ref_list[list][index].reference&3) != 3)) {

                int i;

                av_log(h->avctx, AV_LOG_ERROR, "Missing reference picture\n");

                for (i = 0; i < FF_ARRAY_ELEMS(h->last_pocs); i++)

                    h->last_pocs[i] = INT_MIN;

                return -1;

            }

            av_assert0(av_buffer_get_ref_count(sl->ref_list[list][index].parent->f->buf[0]) > 0);

        }

    }



    return 0;

}

int ff_h264_decode_ref_pic_list_reordering(H264Context *h){

    int list, index, pic_structure, i;



    print_short_term(h);

    print_long_term(h);



    for(list=0; list<h->list_count; list++){

        for (i = 0; i < h->ref_count[list]; i++)

            COPY_PICTURE(&h->ref_list[list][i], &h->default_ref_list[list][i]);



        if(get_bits1(&h->gb)){

            int pred= h->curr_pic_num;



            for(index=0; ; index++){

                unsigned int reordering_of_pic_nums_idc= get_ue_golomb_31(&h->gb);

                unsigned int pic_id;

                int i;

                Picture *ref = NULL;



                if(reordering_of_pic_nums_idc==3)

                    break;



                if(index >= h->ref_count[list]){

                    av_log(h->avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                if(reordering_of_pic_nums_idc<3){

                    if(reordering_of_pic_nums_idc<2){

                        const unsigned int abs_diff_pic_num= get_ue_golomb(&h->gb) + 1;

                        int frame_num;



                        if(abs_diff_pic_num > h->max_pic_num){

                            av_log(h->avctx, AV_LOG_ERROR, "abs_diff_pic_num overflow\n");

                            return -1;

                        }



                        if(reordering_of_pic_nums_idc == 0) pred-= abs_diff_pic_num;

                        else                                pred+= abs_diff_pic_num;

                        pred &= h->max_pic_num - 1;



                        frame_num = pic_num_extract(h, pred, &pic_structure);



                        for(i= h->short_ref_count-1; i>=0; i--){

                            ref = h->short_ref[i];

                            assert(ref->reference);

                            assert(!ref->long_ref);

                            if(

                                   ref->frame_num == frame_num &&

                                   (ref->reference & pic_structure)

                              )

                                break;

                        }

                        if(i>=0)

                            ref->pic_id= pred;

                    }else{

                        int long_idx;

                        pic_id= get_ue_golomb(&h->gb); //long_term_pic_idx



                        long_idx= pic_num_extract(h, pic_id, &pic_structure);



                        if(long_idx>31){

                            av_log(h->avctx, AV_LOG_ERROR, "long_term_pic_idx overflow\n");

                            return -1;

                        }

                        ref = h->long_ref[long_idx];

                        assert(!(ref && !ref->reference));

                        if (ref && (ref->reference & pic_structure)) {

                            ref->pic_id= pic_id;

                            assert(ref->long_ref);

                            i=0;

                        }else{

                            i=-1;

                        }

                    }



                    if (i < 0) {

                        av_log(h->avctx, AV_LOG_ERROR, "reference picture missing during reorder\n");

                        memset(&h->ref_list[list][index], 0, sizeof(Picture)); //FIXME

                    } else {

                        for(i=index; i+1<h->ref_count[list]; i++){

                            if(ref->long_ref == h->ref_list[list][i].long_ref && ref->pic_id == h->ref_list[list][i].pic_id)

                                break;

                        }

                        for(; i > index; i--){

                            COPY_PICTURE(&h->ref_list[list][i], &h->ref_list[list][i - 1]);

                        }

                        COPY_PICTURE(&h->ref_list[list][index], ref);

                        if (FIELD_PICTURE){

                            pic_as_field(&h->ref_list[list][index], pic_structure);

                        }

                    }

                }else{

                    av_log(h->avctx, AV_LOG_ERROR, "illegal reordering_of_pic_nums_idc\n");

                    return -1;

                }

            }

        }

    }

    for(list=0; list<h->list_count; list++){

        for(index= 0; index < h->ref_count[list]; index++){

            if (!h->ref_list[list][index].f.data[0]) {

                int i;

                av_log(h->avctx, AV_LOG_ERROR, "Missing reference picture, default is %d\n", h->default_ref_list[list][0].poc);

                for (i=0; i<FF_ARRAY_ELEMS(h->last_pocs); i++)

                    h->last_pocs[i] = INT_MIN;

                if (h->default_ref_list[list][0].f.data[0])

                    COPY_PICTURE(&h->ref_list[list][index], &h->default_ref_list[list][0]);

                else

                    return -1;

            }

        }

    }



    return 0;

}

int ff_h264_decode_ref_pic_list_reordering(H264Context *h)

{

    int list, index, pic_structure, i;



    print_short_term(h);

    print_long_term(h);



    for (list = 0; list < h->list_count; list++) {

        for (i = 0; i < h->ref_count[list]; i++)

            COPY_PICTURE(&h->ref_list[list][i], &h->default_ref_list[list][i]);



        if (get_bits1(&h->gb)) {

            int pred = h->curr_pic_num;



            for (index = 0; ; index++) {

                unsigned int reordering_of_pic_nums_idc = get_ue_golomb_31(&h->gb);

                unsigned int pic_id;

                int i;

                Picture *ref = NULL;



                if (reordering_of_pic_nums_idc == 3)

                    break;



                if (index >= h->ref_count[list]) {

                    av_log(h->avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                if (reordering_of_pic_nums_idc < 3) {

                    if (reordering_of_pic_nums_idc < 2) {

                        const unsigned int abs_diff_pic_num = get_ue_golomb(&h->gb) + 1;

                        int frame_num;



                        if (abs_diff_pic_num > h->max_pic_num) {

                            av_log(h->avctx, AV_LOG_ERROR, "abs_diff_pic_num overflow\n");

                            return -1;

                        }



                        if (reordering_of_pic_nums_idc == 0)

                            pred -= abs_diff_pic_num;

                        else

                            pred += abs_diff_pic_num;

                        pred &= h->max_pic_num - 1;



                        frame_num = pic_num_extract(h, pred, &pic_structure);



                        for (i = h->short_ref_count - 1; i >= 0; i--) {

                            ref = h->short_ref[i];

                            assert(ref->reference);

                            assert(!ref->long_ref);

                            if (ref->frame_num == frame_num &&

                                (ref->reference & pic_structure))

                                break;

                        }

                        if (i >= 0)

                            ref->pic_id = pred;

                    } else {

                        int long_idx;

                        pic_id = get_ue_golomb(&h->gb); //long_term_pic_idx



                        long_idx = pic_num_extract(h, pic_id, &pic_structure);



                        if (long_idx > 31) {

                            av_log(h->avctx, AV_LOG_ERROR, "long_term_pic_idx overflow\n");

                            return -1;

                        }

                        ref = h->long_ref[long_idx];

                        assert(!(ref && !ref->reference));

                        if (ref && (ref->reference & pic_structure)) {

                            ref->pic_id = pic_id;

                            assert(ref->long_ref);

                            i = 0;

                        } else {

                            i = -1;

                        }

                    }



                    if (i < 0) {

                        av_log(h->avctx, AV_LOG_ERROR, "reference picture missing during reorder\n");

                        memset(&h->ref_list[list][index], 0, sizeof(Picture)); //FIXME

                    } else {

                        for (i = index; i + 1 < h->ref_count[list]; i++) {

                            if (ref->long_ref == h->ref_list[list][i].long_ref &&

                                ref->pic_id   == h->ref_list[list][i].pic_id)

                                break;

                        }

                        for (; i > index; i--) {

                            COPY_PICTURE(&h->ref_list[list][i], &h->ref_list[list][i - 1]);

                        }

                        COPY_PICTURE(&h->ref_list[list][index], ref);

                        if (FIELD_PICTURE(h)) {

                            pic_as_field(&h->ref_list[list][index], pic_structure);

                        }

                    }

                } else {

                    av_log(h->avctx, AV_LOG_ERROR, "illegal reordering_of_pic_nums_idc\n");

                    return -1;

                }

            }

        }

    }

    for (list = 0; list < h->list_count; list++) {

        for (index = 0; index < h->ref_count[list]; index++) {

            if (!h->ref_list[list][index].f.data[0]) {

                av_log(h->avctx, AV_LOG_ERROR, "Missing reference picture\n");

                if (h->default_ref_list[list][0].f.data[0])

                    COPY_PICTURE(&h->ref_list[list][index], &h->default_ref_list[list][0]);

                else

                    return -1;

            }

        }

    }



    return 0;

}

int ff_h264_decode_ref_pic_list_reordering(H264Context *h, H264SliceContext *sl)

{

    int list, index, pic_structure;



    print_short_term(h);

    print_long_term(h);



    for (list = 0; list < sl->list_count; list++) {

        memcpy(sl->ref_list[list], h->default_ref_list[list], sl->ref_count[list] * sizeof(sl->ref_list[0][0]));



        if (get_bits1(&sl->gb)) {    // ref_pic_list_modification_flag_l[01]

            int pred = h->curr_pic_num;



            for (index = 0; ; index++) {

                unsigned int modification_of_pic_nums_idc = get_ue_golomb_31(&sl->gb);

                unsigned int pic_id;

                int i;

                H264Picture *ref = NULL;



                if (modification_of_pic_nums_idc == 3)

                    break;



                if (index >= sl->ref_count[list]) {

                    av_log(h->avctx, AV_LOG_ERROR, "reference count overflow\n");

                    return -1;

                }



                switch (modification_of_pic_nums_idc) {

                case 0:

                case 1: {

                    const unsigned int abs_diff_pic_num = get_ue_golomb(&sl->gb) + 1;

                    int frame_num;



                    if (abs_diff_pic_num > h->max_pic_num) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "abs_diff_pic_num overflow\n");

                        return AVERROR_INVALIDDATA;

                    }



                    if (modification_of_pic_nums_idc == 0)

                        pred -= abs_diff_pic_num;

                    else

                        pred += abs_diff_pic_num;

                    pred &= h->max_pic_num - 1;



                    frame_num = pic_num_extract(h, pred, &pic_structure);



                    for (i = h->short_ref_count - 1; i >= 0; i--) {

                        ref = h->short_ref[i];

                        assert(ref->reference);

                        assert(!ref->long_ref);

                        if (ref->frame_num == frame_num &&

                            (ref->reference & pic_structure))

                            break;

                    }

                    if (i >= 0)

                        ref->pic_id = pred;

                    break;

                }

                case 2: {

                    int long_idx;

                    pic_id = get_ue_golomb(&sl->gb); // long_term_pic_idx



                    long_idx = pic_num_extract(h, pic_id, &pic_structure);



                    if (long_idx > 31) {

                        av_log(h->avctx, AV_LOG_ERROR,

                               "long_term_pic_idx overflow\n");

                        return AVERROR_INVALIDDATA;

                    }

                    ref = h->long_ref[long_idx];

                    assert(!(ref && !ref->reference));

                    if (ref && (ref->reference & pic_structure)) {

                        ref->pic_id = pic_id;

                        assert(ref->long_ref);

                        i = 0;

                    } else {

                        i = -1;

                    }

                    break;

                }

                default:

                    av_log(h->avctx, AV_LOG_ERROR,

                           "illegal modification_of_pic_nums_idc %u\n",

                           modification_of_pic_nums_idc);

                    return AVERROR_INVALIDDATA;

                }



                if (i < 0) {

                    av_log(h->avctx, AV_LOG_ERROR,

                           "reference picture missing during reorder\n");

                    memset(&sl->ref_list[list][index], 0, sizeof(sl->ref_list[0][0])); // FIXME

                } else {

                    for (i = index; i + 1 < sl->ref_count[list]; i++) {

                        if (sl->ref_list[list][i].parent &&

                            ref->long_ref == sl->ref_list[list][i].parent->long_ref &&

                            ref->pic_id   == sl->ref_list[list][i].pic_id)

                            break;

                    }

                    for (; i > index; i--) {

                        sl->ref_list[list][i] = sl->ref_list[list][i - 1];

                    }

                    ref_from_h264pic(&sl->ref_list[list][index], ref);

                    if (FIELD_PICTURE(h)) {

                        pic_as_field(&sl->ref_list[list][index], pic_structure);

                    }

                }

            }

        }

    }

    for (list = 0; list < sl->list_count; list++) {

        for (index = 0; index < sl->ref_count[list]; index++) {

            if (   !sl->ref_list[list][index].parent

                || (!FIELD_PICTURE(h) && (sl->ref_list[list][index].reference&3) != 3)) {

                int i;

                av_log(h->avctx, AV_LOG_ERROR, "Missing reference picture, default is %d\n", h->default_ref_list[list][0].poc);

                for (i = 0; i < FF_ARRAY_ELEMS(h->last_pocs); i++)

                    h->last_pocs[i] = INT_MIN;

                if (h->default_ref_list[list][0].parent

                    && !(!FIELD_PICTURE(h) && (h->default_ref_list[list][0].reference&3) != 3))

                    sl->ref_list[list][index] = h->default_ref_list[list][0];

                else

                    return -1;

            }

            av_assert0(av_buffer_get_ref_count(sl->ref_list[list][index].parent->f->buf[0]) > 0);

        }

    }



    return 0;

}

